head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.ssMarket = "N"; // 종목콤보확인
scwin.stat = "";
scwin.skw = "";
// bizspt/ULDSTF30302(IR처리) 화면에서 테스트
// TOBE : 회사명을 약어로 표시하기로 함(2026.05.29 이창민C)
//       상장구분에 따라 호출되게 수정(ASIS는 시장 콤보박스 바꾸면 상장구분 조회조건 수행X)
//       필터시에 oldComAbbrv 사용안하고 회사명으로만 검색되도록 수정(2026.06.05 이창민C)

scwin.tpcd = $c.stf.getUserInfo($p, "market"); // 세션의 시장구분

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 부모화면의 상장구분 지정값(js_listStatCd)을 수신해 상장구분 콤보를 설정하고,
 *  시장구분 공통코드와 회사목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        scwin.tpcd = "9"; // 현재 세션은 1이라서 임시로 9로 SET
        // 구 $c.frame.path("../") — 부모 화면의 상장구분 지정값(규칙 21: getParent)
        scwin.stat = $c.win.getParent()?.js_listStatCd;// 상장상태여부

        if (scwin.stat === undefined) {
            scwin.stat = "";
        } else {
            const gListStatCd = scwin.stat;
            if (gListStatCd === "Y") {
                sbx_stat.setValue("Y");
                sbx_stat.setDisabled(true);
            }
        }

        scwin.code1Sync();
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 처리 — 별도 처리 없음.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function () {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_jongmok_onkeydown
 * @description 회사목록 그리드 키 입력 — 엔터 키 입력 시 선택 회사를 부모창에 전달한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.grd_jongmok_onkeydown(e);
 */
scwin.grd_jongmok_onkeydown = function (e) {
    try {
        if (e.keyCode === "13") {
            scwin.Confirm();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.grd_jongmok_onkeydown" });
    }
};

/**
 * @method
 * @name grd_jongmok_oncelldblclick
 * @description 회사목록 더블클릭 — 선택한 회사정보를 부모창에 전달하고 팝업을 닫는다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_jongmok_oncelldblclick(0, 0, "comAbbrv");
 */
scwin.grd_jongmok_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.Confirm();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.grd_jongmok_oncelldblclick" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description [조회] 버튼 클릭 — 입력한 회사명을 검색어로 회사목록을 필터 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_search_onclick(e);
 */
scwin.btn_search_onclick = function (e) {
    try {
        // 20250718 진창영부장님 요청 (엔터와 이미지 클릭과 같도록 맞추기로 함)
        scwin.JongmokSearch(ibx_jongmokName.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_search_onclick" });
    }
};

/**
 * @method
 * @name ibx_jongmokName_onkeydown
 * @description 회사명 입력란 키 입력 — 엔터 키 입력 시 입력한 회사명으로 회사목록을 필터 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.ibx_jongmokName_onkeydown(e);
 */
scwin.ibx_jongmokName_onkeydown = function (e) {
    try {
        if (Number(e.keyCode) === 13) {
            scwin.JongmokSearch();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.ibx_jongmokName_onkeydown" });
    }
};

/**
 * @method
 * @name btn_ga_onclick
 * @description [가] 버튼 클릭 — 회사약명 첫 글자가 '가'~'나' 미만 구간인 첫 행으로 목록 포커스를 이동한다.
 * @returns {void}
 * @hidden N
 * @example scwin.btn_ga_onclick();
 */
scwin.btn_ga_onclick = function () {
    try {
