/**
 * @method
 * @name sbx_market_onchange
 * @description 시장 콤보 변경 — 콤보 초기화(ssMarket) 완료 상태에서 선택한 시장구분으로 회사목록을 재조회한다.
 * @param {Object} info 변경 이벤트 정보(newValue)
 * @returns {void}
 * @hidden N
 * @example scwin.sbx_market_onchange(info);
 */
scwin.sbx_market_onchange = function (info) {
    try {
        if (scwin.ssMarket === "Y") {
            ibx_jongmokName.setValue("");
            scwin.skw = "";
            scwin.tpcd = info.newValue;
            scwin.listSync();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.sbx_market_onchange" });
    }
};

/**
 * @method
 * @name sbx_stat_onchange
 * @description 상장구분 콤보 변경 — 선택한 상장구분(전체 선택 시 조건 해제)으로 회사목록을 재조회한다.
 * @param {Object} info 변경 이벤트 정보(newValue)
 * @returns {void}
 * @hidden N
 * @example scwin.sbx_stat_onchange(info);
 */
scwin.sbx_stat_onchange = function (info) {
    try {
        ibx_jongmokName.setValue("");
        scwin.stat = info.newValue;

        if (scwin.stat === '0') {
            scwin.stat = "";
        }

        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.sbx_stat_onchange" });
    }
};

/**
 * @method
 * @name dlt_jongmok_OnFilter
 * @description 회사목록 필터 적용 — 기존 필터를 모두 제거하고, 검색어(skw)가 있으면 회사약명 컬럼에 부분일치 필터를 적용한다.
 * @returns {void}
 * @hidden N
 * @example scwin.dlt_jongmok_OnFilter();
 */
scwin.dlt_jongmok_OnFilter = function () {
    try {
        dlt_jongmok.removeColumnFilterAll();

        if (scwin.skw !== "") {
            dlt_jongmok.setColumnFilter({ type: "row", colIndex: "comAbbrv", key: scwin.skw, condition: "and", exactMatch: false });
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.dlt_jongmok_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name sbm_jongmok_submitdone
 * @description 회사목록 조회(sbm_jongmok) 완료 콜백 — 첫 행의 회사약명 셀에 포커스를 준다.
 * @param {Object} e 서브미션 완료 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_jongmok_submitdone(e);
 */
scwin.sbm_jongmok_submitdone = function (e) {
    grd_jongmok.setFocusedCell(0, "comAbbrv");
};

/**
 * @method
 * @name sbm_code1_submitdone
 * @description 시장구분 공통코드 조회(sbm_code1) 완료 콜백 — 시장 콤보를 초기 설정한다.
 * @param {Object} e 서브미션 완료 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_code1_submitdone(e);
 */
scwin.sbm_code1_submitdone = function (e) {
    scwin.marketSetCombo();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description 시장구분·상장구분 조건으로 회사목록을 조회한다(sbm_jongmok 실행).
 * @returns {void}
 * @hidden N
 * @example scwin.listSync();
 */
scwin.listSync = function () {
    const url = "/api/discls/common/popup/select-list-isur-cd-value?mktTpCd=" + scwin.tpcd + "&listStatCd=" + scwin.stat;

    $c.sbm.setAction(sbm_jongmok, url);
    $c.sbm.execute(sbm_jongmok);
};

/**
 * @method
 * @name Jongmok
 * @description 가나다라..검색 — 필터를 초기화하고 회사약명 기준 정렬 후, 첫 글자가 지정 구간에 드는 첫 행으로 그리드 포커스를 이동한다.
 * @param {String} prevval 구간 시작 문자
 * @param {String} nextval 구간 종료 경계 문자(미만)
 * @returns {void}
 * @hidden N
 * @example scwin.Jongmok('가', '나');
 */
scwin.Jongmok = function (prevval, nextval) {
    ibx_jongmokName.setValue("");
    scwin.skw = "";
    scwin.dlt_jongmok_OnFilter();

    dlt_jongmok.sort("comAbbrv", 0);

    let cnt = 0;
    for (let i = 0; i < dlt_jongmok.getRowCount(); i++) {
        const name = dlt_jongmok.getCellData(i, "comAbbrv").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }

    grd_jongmok.setFocusedCell(cnt + 10, "comAbbrv");
    grd_jongmok.setFocusedCell(cnt, "comAbbrv");
};

/**
 * @method
 * @name JongmokName
 * @description 종목명검색 — (TOBE) 필터 방식으로 대체되어 회사목록 필터만 재적용한다(기존 정렬·포커스 이동 로직은 주석 보존).
 * @param {String} keyCode 입력 키 값(레거시 인자, 현재 미사용)
 * @returns {void}
 * @hidden N
