/**
 * @method
 * @name JongmokSearch
 * @description 종목명검색 — 입력한 회사명을 검색어(skw)로 필터를 적용하고 첫 행의 회사약명 셀에 포커스를 준다.
 * @returns {void}
 * @hidden N
 * @example scwin.JongmokSearch();
 */
scwin.JongmokSearch = function () {
    scwin.skw = ibx_jongmokName.getValue();

    scwin.dlt_jongmok_OnFilter();
    grd_jongmok.setFocusedCell(0, "comAbbrv");
};

/**
 * @method
 * @name Confirm
 * @description 부모창으로 종목코드 전달 — 선택 행의 발행기관코드·회사약명·시장구분을 부모창에 전달($c.cm.isurSearch_Rtn)하고 팝업을 닫는다.
 * @returns {void}
 * @hidden N
 * @example await scwin.Confirm();
 */
scwin.Confirm = async function () {
    const pJongCode = dlt_jongmok.getCellData(dlt_jongmok.getRowPosition(), "isurCd");
    const pJongNm = dlt_jongmok.getCellData(dlt_jongmok.getRowPosition(), "comAbbrv");
    const ld_mkt_tp_cd = dlt_jongmok.getCellData(dlt_jongmok.getRowPosition(), "spotIsuTrdMktTpCd");

    $c.cm.isurSearch_Rtn(pJongCode, pJongNm, ld_mkt_tp_cd);
    await $c.win.closePopup();
};

/**
 * @method
 * @name code1Sync
 * @description 시장구분 공통코드(SPOT_ISU_TRD_MKT_TP_CD) 목록을 조회한다(sbm_code1 실행).
 * @returns {void}
 * @hidden N
 * @example scwin.code1Sync();
 */
scwin.code1Sync = function () {
    const url = "/api/discls/common/code/select-list-code-value?type=R&cdEngNm=SPOT_ISU_TRD_MKT_TP_CD";
    $c.sbm.setAction(sbm_code1, url);
    $c.sbm.execute(sbm_code1);
};

/**
 * @method
 * @name marketSetCombo
 * @description 세션 시장구분(tpcd)으로 시장 콤보를 초기 설정한다 — 사용자의 시장구분값이 유효하지 않으면 '조건없음'으로
 *  초기화 후 재조회하고, 유가증권·코스닥이면 콤보를 비활성화한다.
 * @returns {void}
 * @hidden N
 * @example scwin.marketSetCombo();
 */
scwin.marketSetCombo = function () {
    if (scwin.tpcd !== "") {
        // 사용자의 시장구분값이 없을 시 '조건없음' 으로 초기화
        if (scwin.tpcd !== "1" && scwin.tpcd !== "2" && scwin.tpcd !== "6") {
            sbx_market.setSelectedIndex(0);
            ibx_jongmokName.setValue("");
            scwin.skw = "";
            scwin.tpcd = sbx_market.getValue();
            scwin.listSync();
        } else {
            sbx_market.setValue(scwin.tpcd);
        }
    }

    if (scwin.tpcd === "1" || scwin.tpcd === "2") {
        sbx_market.setDisabled(true);
    }
    scwin.ssMarket = "Y";
};

/**
 * @method
 * @name spotIsuTrdMktTpCdExp
 * @description 시장구분 컬럼 customFormatter — 상장구분코드에 따라 회사약명 셀 색상을 설정한다(상장:검정, 상장폐지:빨강, 비상장:초록).
 * @param {String} data 셀 원본 값
 * @param {String} formattedData 표시 값
 * @param {Number} rowIdx 행 인덱스
 * @param {Number} colIdx 컬럼 인덱스
 * @returns {String} 표시 값(formattedData)
 * @hidden N
 * @example (grd_jongmok spotIsuTrdMktTpCd 컬럼 customFormatter 바인딩으로 자동 호출)
 */
scwin.spotIsuTrdMktTpCdExp = function (data, formattedData, rowIdx, colIdx) {
    const listStatCd = dlt_jongmok.getCellData(rowIdx, "listStatCd");

    if (listStatCd === "Y") {
        grd_jongmok.setCellColor(rowIdx, "comAbbrv", "#000000");
    } else if (listStatCd === "D") {
        grd_jongmok.setCellColor(rowIdx, "comAbbrv", "#FF0033");
    } else if (listStatCd === "N") {
        grd_jongmok.setCellColor(rowIdx, "comAbbrv", "#009933");
    }

    return formattedData;
};
